"""Summarize mailtodo letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


RESOLUTIONS = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")
NAME = re.compile(r"[0-9]{8}T[0-9]{4}[-_]")


def frontmatter(path):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None
    if not lines or lines[0] != "---":
        return None
    fields = {}
    for line in lines[1:]:
        if line == "---":
            return fields
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    return None


def letters_in(root):
    boxes = {}
    files = []
    for box in root.iterdir():
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, directory in (("inbox", inbox), ("done", inbox / "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (not path.name.startswith(".") and path.suffix == ".md"
                        and not path.is_symlink() and path.is_file()):
                    files.append((path.relative_to(root).as_posix(), path, box.name, where))
    return {name: boxes[name] for name in sorted(boxes)}, sorted(files)


def summarize(root, now):
    boxes, files = letters_in(root)
    bad, valid, seen = [], [], set()
    for relative, path, box, where in files:
        fields = frontmatter(path)
        if fields is None:
            why = "no_frontmatter"
        elif any(not fields.get(key) for key in REQUIRED):
            why = "no_field"
        else:
            try:
                at = datetime.fromisoformat(fields["at"])
            except ValueError:
                why = "no_field"
            else:
                if not NAME.match(path.name):
                    why = "bad_name"
                else:
                    try:
                        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
                    except ValueError:
                        why = "bad_name"
                    else:
                        why = "dup_id" if fields["id"] in seen else None
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(fields["id"])
        if at.tzinfo is None:
            at = at.replace(tzinfo=now.tzinfo)
        valid.append((fields, where, at))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            status = fields["status"]
            counts[status] = counts.get(status, 0) + 1
    resolved = {fields["re"] for fields, _, _ in valid
                if fields.get("re") and fields["status"] in RESOLUTIONS}
    opened = [{"id": fields["id"], "from": fields["from"], "to": fields["to"],
               "where": where, "age_min": (now - at) // timedelta(minutes=1)}
              for fields, where, at in valid
              if fields["status"] == "REQUEST" and fields["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    for box in boxes.values():
        box["inbox"] = dict(sorted(box["inbox"].items()))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailtodo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
